export function DetailView({
  name = "{{name}}",
  status = "{{status}}",
  layout = "{{layout}}",
  accent = "{{accent}}",
  notes = {{notes}},
  radius = {{radius}},
}) {
  const badgeColors = { active: "#A8E6C1", pending: "#E8A020", closed: "#24143018" };
  const fields = [
    { label: "Customer", value: "Priya Nair" },
    { label: "Email", value: "priya@example.com" },
    { label: "Placed", value: <time dateTime="2026-08-12T09:30:00Z">12 Aug 2026, 9:30am</time> },
    { label: "Total", value: "£128.00" },
    { label: "Shipping", value: "14 Elm Road, Bristol BS1 4ST" },
  ];
  const twoColumn = layout === "two-column";
  const dlStyle = twoColumn ? { display: "grid", gridTemplateColumns: "1fr 1fr", gap: "4px 28px" } : { display: "block" };
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", border: "1.5px solid #24143022", borderTop: `4px solid ${accent}`, borderRadius: radius, padding: 20, boxSizing: "border-box" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
        <h2 style={{ margin: 0, fontSize: 18, fontWeight: 600 }}>{name}</h2>
        <span style={{ fontSize: 11, fontWeight: 600, textTransform: "capitalize", padding: "3px 10px", borderRadius: 999, background: badgeColors[status] ?? accent, color: "#241430" }}>{status}</span>
      </div>
      <dl style={{ margin: 0, ...dlStyle }}>
        {fields.map((f) => (
          <div key={f.label} style={{ marginBottom: twoColumn ? 4 : 16 }}>
            <dt style={{ fontSize: 12, textTransform: "uppercase", letterSpacing: ".03em", color: "#24143099", marginBottom: 2 }}>{f.label}</dt>
            <dd style={{ margin: 0, fontSize: 14 }}>{f.value}</dd>
          </div>
        ))}
        {notes && (
          <div style={{ borderTop: "1px dashed #24143022", paddingTop: 10, marginTop: 4, gridColumn: twoColumn ? "1 / -1" : "auto" }}>
            <dt style={{ fontSize: 12, textTransform: "uppercase", letterSpacing: ".03em", color: "#24143099", marginBottom: 2 }}>Notes</dt>
            <dd style={{ margin: 0, fontSize: 14 }}>Gift wrap requested; leave with neighbour if out.</dd>
          </div>
        )}
      </dl>
    </div>
  );
}
